/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { runLeadMagnetRuntime } from "../_shared/leadMagnet/runLeadMagnetRuntime.ts";
import { handleLeadMagnetPostbackTrigger } from "../_shared/leadMagnet/postbackHandler.ts";
import { resendLeadMagnetDeliveryDm } from "../_shared/leadMagnet/followGateRuntime.ts";
import { resolveLeadMagnetEntitlement } from "../_shared/leadMagnet/leadMagnetEntitlement.ts";
import {
  buildLeadMagnetPostbackPayload,
  type FollowConfirmResult,
  type LeadMagnetRuntimeInput,
} from "../_shared/leadMagnet/types.ts";
import {
  verifyLeadMagnetActionUrl,
  buildSpaRedirectHtml,
  buildDownloadLandingHtml,
  wantsJsonActionApi,
  type LeadMagnetAction,
  type DownloadLandingBody,
} from "../_shared/leadMagnet/leadMagnetActionUrl.ts";

const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, accept",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

function isAuthorizedServiceCall(req: Request): boolean {
  const serviceRoleKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "").trim();
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) return false;
  if (serviceRoleKey && token === serviceRoleKey) return true;
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return false;
    const payload = JSON.parse(atob(parts[1].replace(/-/g, "+").replace(/_/g, "/"))) as {
      role?: string;
      ref?: string;
      iss?: string;
    };
    const projectRef = (Deno.env.get("SUPABASE_URL") ?? "").match(/https:\/\/([^.]+)\.supabase\.co/)?.[1] ?? "";
    const roleOk = payload.role === "service_role";
    const refOk = !projectRef || payload.ref === projectRef || (payload.iss ?? "").includes(projectRef);
    return roleOk && refOk;
  } catch {
    return false;
  }
}

type ActionResponseBody = {
  ok: boolean;
  code: string;
  title: string;
  message: string;
  pageUrl?: string | null;
};

function wantsHtml(req: Request): boolean {
  const accept = (req.headers.get("Accept") ?? "").toLowerCase();
  return accept.includes("text/html") && !accept.includes("application/json");
}

function actionResponse(req: Request, body: ActionResponseBody, status = 200): Response {
  if (wantsHtml(req)) {
    const pageLink = body.pageUrl
      ? `<p style="margin-top:1rem"><a href="${body.pageUrl}" style="color:#2563eb">Buka Page Facebook</a></p>`
      : "";
    const html = `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />
  <title>${body.title}</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center; background: #f3f4f6; color: #111827; }
    .card { max-width: 22rem; padding: 1.5rem; border-radius: 0.75rem; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.12); text-align: center; }
    h1 { font-size: 1.125rem; margin: 0 0 0.5rem; }
    p { margin: 0; font-size: 0.9375rem; line-height: 1.5; color: #4b5563; }
  </style>
</head>
<body>
  <div class="card">
    <h1>${body.title}</h1>
    <p>${body.message}</p>
    ${pageLink}
  </div>
</body>
</html>`;
    return new Response(html, {
      status,
      headers: { "Content-Type": "text/html; charset=utf-8", ...corsHeaders },
    });
  }

  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...corsHeaders },
  });
}

function mapFollowConfirmResult(
  result: FollowConfirmResult,
  pageUrl: string | null,
): ActionResponseBody {
  if (result.outcome === "blocked" && result.reason === "fb_first_confirm") {
    return {
      ok: true,
      code: "fb_first_confirm",
      title: "Ikuti Page dulu",
      message: "Ikuti Page Facebook terlebih dahulu, lalu kembali ke Messenger dan klik Sudah Follow lagi.",
      pageUrl,
    };
  }
  if (result.outcome === "blocked" && result.reason === "ig_not_following") {
    return {
      ok: true,
      code: "ig_not_following",
      title: "Belum follow",
      message: "Akun Instagram belum follow. Follow dulu, lalu klik Sudah Follow lagi di DM.",
      pageUrl: null,
    };
  }
  if (result.outcome === "dm_failed") {
    return {
      ok: false,
      code: "dm_failed",
      title: "Pesan belum terkirim",
      message: "Messenger menolak pengiriman DM. Kembali ke Messenger, klik tombol Sudah Follow di chat (bukan link browser), lalu coba lagi.",
      pageUrl: null,
    };
  }
  if (result.outcome === "already_processed") {
    return {
      ok: true,
      code: "already_processed",
      title: "Sudah diproses",
      message: "Permintaan sudah pernah diproses. Cek Messenger Anda.",
      pageUrl: null,
    };
  }
  return {
    ok: true,
    code: "material_sent",
    title: "Terima kasih!",
    message: "Cek Messenger — pesan materi akan segera dikirim.",
    pageUrl: null,
  };
}

async function resolvePageCredentials(
  admin: ReturnType<typeof createClient>,
  organizationId: string,
  accountId: string,
): Promise<{ pageId: string; accessToken: string; pageUrl: string | null } | null> {
  const { data: fbPage } = await admin
    .from("organization_facebook_pages")
    .select("facebook_page_id, page_access_token, page_name")
    .eq("organization_id", organizationId)
    .eq("facebook_page_id", accountId)
    .eq("is_active", true)
    .maybeSingle();
  const fbToken = (fbPage?.page_access_token as string | null)?.trim() ?? "";
  if (fbPage?.facebook_page_id && fbToken) {
    const pageId = String(fbPage.facebook_page_id).trim();
    return {
      pageId,
      accessToken: fbToken,
      pageUrl: `https://www.facebook.com/${encodeURIComponent(pageId)}`,
    };
  }

  const { data: igRow } = await admin
    .from("organization_instagram_accounts")
    .select("facebook_page_id, page_access_token")
    .eq("organization_id", organizationId)
    .eq("instagram_business_account_id", accountId)
    .eq("is_active", true)
    .maybeSingle();
  const igToken = (igRow?.page_access_token as string | null)?.trim() ?? "";
  const pageId = (igRow?.facebook_page_id as string | null)?.trim() ?? "";
  if (pageId && igToken) {
    return {
      pageId,
      accessToken: igToken,
      pageUrl: `https://www.facebook.com/${encodeURIComponent(pageId)}`,
    };
  }

  return null;
}

async function handleActionGet(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const enrollmentId = (url.searchParams.get("e") ?? "").trim();
  const action = (url.searchParams.get("a") ?? "").trim() as LeadMagnetAction;
  const expiry = (url.searchParams.get("t") ?? "").trim();
  const sig = (url.searchParams.get("s") ?? "").trim();

  // Messenger / browser opened edge URL directly (legacy buttons) → redirect to SPA.
  if (!wantsJsonActionApi(req)) {
    const qs = url.searchParams.toString();
    const html = buildSpaRedirectHtml(qs);
    return new Response(html, {
      status: 200,
      headers: { "Content-Type": "text/html; charset=utf-8", ...corsHeaders },
    });
  }

  if (!enrollmentId || !action || !expiry || !sig) {
    return actionResponse(req, {
      ok: false,
      code: "invalid_params",
      title: "Link tidak valid",
      message: "Parameter tautan tidak lengkap.",
    }, 400);
  }

  const valid = await verifyLeadMagnetActionUrl(enrollmentId, action, expiry, sig);
  if (!valid) {
    return actionResponse(req, {
      ok: false,
      code: "expired",
      title: "Link kedaluwarsa",
      message: "Silakan kembali ke Messenger dan minta link baru.",
    }, 400);
  }

  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const admin = createClient(supabaseUrl, serviceRoleKey);

  const { data: enrollment, error } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("id", enrollmentId)
    .maybeSingle();

  if (error || !enrollment) {
    return actionResponse(req, {
      ok: false,
      code: "not_found",
      title: "Tidak ditemukan",
      message: "Enrollment tidak ditemukan.",
    }, 404);
  }

  const campaignRaw = (enrollment as { campaign?: unknown }).campaign;
  const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
  if (!campaign) {
    return actionResponse(req, {
      ok: false,
      code: "campaign_missing",
      title: "Kampanye tidak ditemukan",
      message: "Data kampanye tidak tersedia.",
    }, 404);
  }

  const orgId = String(enrollment.organization_id);
  const accountId = String(campaign.account_id);
  const creds = await resolvePageCredentials(admin, orgId, accountId);
  if (!creds) {
    return actionResponse(req, {
      ok: false,
      code: "page_credentials",
      title: "Koneksi Page bermasalah",
      message: "Token Page tidak ditemukan. Hubungi admin.",
    }, 503);
  }

  const entitlement = await resolveLeadMagnetEntitlement(admin, orgId);
  if (!entitlement.entitled) {
    return actionResponse(req, {
      ok: false,
      code: "not_entitled",
      title: "Tidak tersedia",
      message: "Fitur Lead Magnet tidak aktif untuk organisasi ini.",
    }, 403);
  }

  if (action === "get_framework" && enrollment.status === "delivered") {
    return actionResponse(req, {
      ok: true,
      code: "already_processed",
      title: "Sudah diproses",
      message: "Materi sudah pernah dikirim. Cek Messenger Anda.",
    });
  }

  const payload = buildLeadMagnetPostbackPayload(enrollmentId, action);
  const input: LeadMagnetRuntimeInput = {
    trigger: "postback",
    platform: enrollment.platform as "instagram" | "facebook",
    organizationId: orgId,
    accountId,
    participantScopedId: String(enrollment.participant_scoped_id),
    participantUsername: (enrollment.participant_username as string | null) ?? null,
    payload,
    conversationId: (enrollment.conversation_id as string | null) ?? null,
    accessToken: creds.accessToken,
    pageId: creds.pageId,
  };

  const result = await handleLeadMagnetPostbackTrigger(admin, input);

  if (action === "follow_confirm") {
    if (result.followConfirm) {
      return actionResponse(req, mapFollowConfirmResult(result.followConfirm, creds.pageUrl));
    }
    return actionResponse(req, {
      ok: result.handled,
      code: result.handled ? "processed" : "failed",
      title: result.handled ? "Terima kasih!" : "Gagal",
      message: result.handled
        ? "Cek Messenger — pesan materi akan segera dikirim."
        : "Permintaan tidak dapat diproses.",
    });
  }

  return actionResponse(req, {
    ok: result.handled,
    code: result.handled ? "delivery_sent" : "failed",
    title: result.handled ? "Materi dikirim!" : "Gagal",
    message: result.handled
      ? "Cek Messenger untuk link materi."
      : "Permintaan tidak dapat diproses.",
  });
}

type DownloadResponseBody = DownloadLandingBody;

function downloadFileNameFromUrl(fileUrl: string): string {
  try {
    const name = decodeURIComponent(new URL(fileUrl).pathname.split("/").pop() ?? "");
    return name || "materi";
  } catch {
    return "materi";
  }
}

function downloadHtmlResponse(body: DownloadResponseBody, status = 200): Response {
  return new Response(buildDownloadLandingHtml(body), {
    status,
    headers: { "Content-Type": "text/html; charset=utf-8", ...corsHeaders },
  });
}

async function resolveDownloadBody(
  enrollmentId: string,
  expiry: string,
  sig: string,
): Promise<{ status: number; body: DownloadResponseBody }> {
  const action: LeadMagnetAction = "download";

  if (!enrollmentId || !expiry || !sig) {
    return {
      status: 400,
      body: {
        ok: false,
        code: "invalid_params",
        title: "Link tidak valid",
        message: "Parameter tautan tidak lengkap.",
      },
    };
  }

  const valid = await verifyLeadMagnetActionUrl(enrollmentId, action, expiry, sig);
  if (!valid) {
    return {
      status: 400,
      body: {
        ok: false,
        code: "expired",
        title: "Link kedaluwarsa",
        message: "Silakan kembali ke Messenger dan minta link baru.",
      },
    };
  }

  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const admin = createClient(supabaseUrl, serviceRoleKey);

  const { data: enrollment, error } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("id", enrollmentId)
    .maybeSingle();

  if (error || !enrollment) {
    return {
      status: 404,
      body: {
        ok: false,
        code: "not_found",
        title: "Tidak ditemukan",
        message: "Enrollment tidak ditemukan.",
      },
    };
  }

  const campaignRaw = (enrollment as { campaign?: unknown }).campaign;
  const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
  const fileUrl = String(campaign?.delivery_url ?? "").trim();
  if (!fileUrl) {
    return {
      status: 404,
      body: {
        ok: false,
        code: "file_missing",
        title: "Materi tidak tersedia",
        message: "File materi belum dikonfigurasi untuk kampanye ini.",
      },
    };
  }

  return {
    status: 200,
    body: {
      ok: true,
      code: "ready",
      title: "Materi siap diunduh",
      message: "Klik tombol di bawah untuk mengunduh file materi Anda.",
      fileUrl,
      buttonLabel: String(campaign?.delivery_button_label ?? "Unduh"),
      fileName: downloadFileNameFromUrl(fileUrl),
    },
  };
}

async function handleDownloadGet(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const enrollmentId = (url.searchParams.get("e") ?? "").trim();
  const expiry = (url.searchParams.get("t") ?? "").trim();
  const sig = (url.searchParams.get("s") ?? "").trim();

  const resolved = await resolveDownloadBody(enrollmentId, expiry, sig);

  if (!wantsJsonActionApi(req)) {
    // Legacy buttons still open Supabase edge URL — redirect to file; gateway serves HTML as text/plain.
    if (resolved.body.ok && resolved.body.fileUrl) {
      return Response.redirect(resolved.body.fileUrl, 302);
    }
    return downloadHtmlResponse(resolved.body, resolved.status);
  }

  return new Response(JSON.stringify(resolved.body), {
    status: resolved.status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...corsHeaders },
  });
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 200, headers: corsHeaders });
  }

  const pathname = new URL(req.url).pathname;
  if (req.method === "GET" && pathname.endsWith("/action")) {
    return handleActionGet(req);
  }
  if (req.method === "GET" && pathname.endsWith("/download")) {
    return handleDownloadGet(req);
  }

  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();

  if (req.method === "POST" && pathname.endsWith("/resend-delivery")) {
    if (!isAuthorizedServiceCall(req)) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    let payload: { enrollmentId?: string };
    try {
      payload = await req.json() as { enrollmentId?: string };
    } catch {
      return new Response(JSON.stringify({ error: "Invalid JSON" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const enrollmentId = (payload.enrollmentId ?? "").trim();
    if (!enrollmentId) {
      return new Response(JSON.stringify({ error: "Missing enrollmentId" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const admin = createClient(supabaseUrl, serviceRoleKey);
    const { data: enrollment, error } = await admin
      .from("lead_magnet_enrollments")
      .select("*, campaign:lead_magnet_campaigns(*)")
      .eq("id", enrollmentId)
      .maybeSingle();
    if (error || !enrollment) {
      return new Response(JSON.stringify({ error: "Enrollment not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const campaignRaw = (enrollment as { campaign?: unknown }).campaign;
    const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
    if (!campaign) {
      return new Response(JSON.stringify({ error: "Campaign not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const orgId = String(enrollment.organization_id);
    const accountId = String(campaign.account_id);
    const creds = await resolvePageCredentials(admin, orgId, accountId);
    if (!creds) {
      return new Response(JSON.stringify({ error: "Page credentials missing" }), {
        status: 503,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }
    const result = await resendLeadMagnetDeliveryDm(admin, {
      enrollment: enrollment as Parameters<typeof resendLeadMagnetDeliveryDm>[1]["enrollment"],
      campaign,
      accessToken: creds.accessToken,
      pageId: creds.pageId,
    });
    return new Response(JSON.stringify({ success: result.ok, ...result }), {
      status: result.ok ? 200 : 502,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  if (!isAuthorizedServiceCall(req)) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  let body: LeadMagnetRuntimeInput;
  try {
    body = await req.json() as LeadMagnetRuntimeInput;
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const admin = createClient(supabaseUrl, serviceRoleKey);

  const handled = await runLeadMagnetRuntime(admin, body);

  return new Response(JSON.stringify({ success: true, handled }), {
    status: 200,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
});

import type { MetaContentPlatform } from "./metaContentAuth.ts";
import { graphUrl } from "./metaContentAuth.ts";
import { metaGraphVersion } from "./metaPlatformScopes.ts";

/** Accepts YYYY-MM-DD or unix timestamp strings for Graph API since/until. */
export function toMetaGraphSinceUntil(
  dateStart: string,
  dateEnd: string,
): { since: string; until: string } {
  const nowSec = Math.floor(Date.now() / 1000);
  const defaultSince = String(nowSec - 7 * 86400);
  const defaultUntil = String(nowSec);
  const maxSpanSec = 30 * 86400;

  const parseInput = (raw: string, endOfDay: boolean): string => {
    const trimmed = raw.trim();
    if (!trimmed) return "";
    if (/^\d+$/.test(trimmed)) return trimmed;
    const ymd = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (ymd) {
      const [, y, m, d] = ymd;
      const date = new Date(
        Date.UTC(
          Number(y),
          Number(m) - 1,
          Number(d),
          endOfDay ? 23 : 0,
          endOfDay ? 59 : 0,
          endOfDay ? 59 : 0,
        ),
      );
      return String(Math.floor(date.getTime() / 1000));
    }
    const parsed = Date.parse(trimmed);
    if (Number.isFinite(parsed)) return String(Math.floor(parsed / 1000));
    return "";
  };

  let sinceSec = Number(parseInput(dateStart, false) || defaultSince);
  let untilSec = Number(parseInput(dateEnd, true) || defaultUntil);

  if (!Number.isFinite(sinceSec)) sinceSec = Number(defaultSince);
  if (!Number.isFinite(untilSec)) untilSec = Number(defaultUntil);
  if (untilSec > nowSec) untilSec = nowSec;
  if (sinceSec > untilSec) sinceSec = untilSec;
  if (untilSec - sinceSec > maxSpanSec) {
    sinceSec = untilSec - maxSpanSec;
  }

  return { since: String(sinceSec), until: String(untilSec) };
}

export type MetaContentPost = {
  id: string;
  caption: string | null;
  media_type: string | null;
  media_url: string | null;
  thumbnail_url: string | null;
  permalink: string | null;
  timestamp: string | null;
  comment_count: number;
  like_count: number;
  shares_count?: number;
  /** Populated when Facebook post list includes inline insights field expansion. */
  insight_views?: number;
  insight_reach?: number;
};

export type MetaContentComment = {
  id: string;
  media_id: string;
  text: string;
  author_name: string;
  author_id: string | null;
  like_count: number;
  reply_count: number;
  parent_comment_id: string | null;
  published_at: string | null;
  is_owner: boolean;
  can_reply: boolean;
};

type GraphError = { error?: { message?: string; code?: number } };

async function graphGet<T>(url: string, accessToken: string): Promise<T> {
  const sep = url.includes("?") ? "&" : "?";
  const res = await fetch(`${url}${sep}access_token=${encodeURIComponent(accessToken)}`);
  const data = await res.json().catch(() => ({})) as T & GraphError;
  if (!res.ok || data?.error) {
    throw new Error(data?.error?.message ?? `Graph API error ${res.status}`);
  }
  return data;
}

async function graphPost<T>(url: string, accessToken: string, body: Record<string, string>): Promise<T> {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ ...body, access_token: accessToken }).toString(),
  });
  const data = await res.json().catch(() => ({})) as T & GraphError;
  if (!res.ok || data?.error) {
    throw new Error(data?.error?.message ?? `Graph API error ${res.status}`);
  }
  return data;
}

const GRAPH_BATCH_LIMIT = 50;
const GRAPH_BATCH_RETRY_CHUNK = 8;
const GRAPH_BATCH_INTER_CHUNK_DELAY_MS = 300;

type GraphBatchItemResult = { code: number; body: string };

function sleepMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isGraphBatchItemSuccess(item: GraphBatchItemResult | undefined): boolean {
  return Boolean(item && item.code >= 200 && item.code < 300);
}

async function graphBatchGet(
  accessToken: string,
  relativeUrls: string[],
): Promise<GraphBatchItemResult[]> {
  if (relativeUrls.length === 0) return [];
  const version = metaGraphVersion();
  const url = `https://graph.facebook.com/${version}/`;
  const batchPayload = relativeUrls.map((relative_url) => ({
    method: "GET",
    relative_url,
  }));
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: accessToken,
      batch: JSON.stringify(batchPayload),
    }).toString(),
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    throw new Error(`Graph batch error ${res.status}`);
  }
  return Array.isArray(data) ? (data as GraphBatchItemResult[]) : [];
}

async function graphBatchGetResilient(
  accessToken: string,
  relativeUrls: string[],
): Promise<GraphBatchItemResult[]> {
  const attempts = 3;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      const results = await graphBatchGet(accessToken, relativeUrls);
      if (results.length === relativeUrls.length) return results;
    } catch (err) {
      if (attempt === attempts - 1) {
        console.warn(
          "graphBatchGetResilient failed:",
          err instanceof Error ? err.message : err,
        );
      }
    }
    await sleepMs(GRAPH_BATCH_INTER_CHUNK_DELAY_MS * (attempt + 1));
  }
  return relativeUrls.map(() => ({ code: 0, body: "" }));
}

function igInsightsRelativeUrl(mediaId: string, params: Record<string, string>): string {
  return `${mediaId}/insights?${new URLSearchParams(params).toString()}`;
}

function isInstagramReelsMediaType(mediaType: string | null | undefined): boolean {
  return String(mediaType ?? "").toUpperCase() === "REELS";
}

function parseBatchInsightBody(body: string): Record<string, number> {
  try {
    const parsed = JSON.parse(body) as { data?: IgInsightMetricRow[] };
    return parseIgInsightMetrics(parsed.data);
  } catch {
    return {};
  }
}

function parseBatchMediaViewFieldsBody(body: string): number {
  try {
    const parsed = JSON.parse(body) as {
      view_count?: number;
      views_count?: number;
      total_views_count?: number;
    };
    return Number(parsed.total_views_count ?? parsed.views_count ?? parsed.view_count ?? 0) || 0;
  } catch {
    return 0;
  }
}

async function mergeIgInsightBatchPass(
  posts: MetaContentPost[],
  accessToken: string,
  mergedById: Map<string, Record<string, number>>,
  relativeUrlForPost: (post: MetaContentPost) => string,
): Promise<void> {
  const failedPosts: MetaContentPost[] = [];

  for (let i = 0; i < posts.length; i += GRAPH_BATCH_LIMIT) {
    if (i > 0) await sleepMs(GRAPH_BATCH_INTER_CHUNK_DELAY_MS);
    const chunk = posts.slice(i, i + GRAPH_BATCH_LIMIT);
    const batchResults = await graphBatchGetResilient(
      accessToken,
      chunk.map(relativeUrlForPost),
    );
    chunk.forEach((post, idx) => {
      const item = batchResults[idx];
      if (!isGraphBatchItemSuccess(item)) {
        failedPosts.push(post);
        return;
      }
      const parsed = parseBatchInsightBody(item.body);
      mergedById.set(post.id, { ...(mergedById.get(post.id) ?? {}), ...parsed });
    });
  }

  for (let i = 0; i < failedPosts.length; i += GRAPH_BATCH_RETRY_CHUNK) {
    await sleepMs(GRAPH_BATCH_INTER_CHUNK_DELAY_MS);
    const chunk = failedPosts.slice(i, i + GRAPH_BATCH_RETRY_CHUNK);
    const batchResults = await graphBatchGetResilient(
      accessToken,
      chunk.map(relativeUrlForPost),
    );
    chunk.forEach((post, idx) => {
      const item = batchResults[idx];
      if (!isGraphBatchItemSuccess(item)) return;
      const parsed = parseBatchInsightBody(item.body);
      mergedById.set(post.id, { ...(mergedById.get(post.id) ?? {}), ...parsed });
    });
  }
}

async function mergeIgMediaViewFieldsBatchPass(
  posts: MetaContentPost[],
  accessToken: string,
  viewCountById: Map<string, number>,
): Promise<void> {
  for (let i = 0; i < posts.length; i += GRAPH_BATCH_LIMIT) {
    if (i > 0) await sleepMs(GRAPH_BATCH_INTER_CHUNK_DELAY_MS);
    const chunk = posts.slice(i, i + GRAPH_BATCH_LIMIT);
    const batchResults = await graphBatchGetResilient(
      accessToken,
      chunk.map((post) => `${post.id}?fields=view_count,views_count,total_views_count`),
    );
    chunk.forEach((post, idx) => {
      const item = batchResults[idx];
      if (!isGraphBatchItemSuccess(item)) return;
      const views = parseBatchMediaViewFieldsBody(item.body);
      if (views > 0) viewCountById.set(post.id, views);
    });
  }
}

async function fetchInstagramMediaInsightsSingleMerged(
  mediaId: string,
  accessToken: string,
  mediaType?: string | null,
): Promise<Record<string, number>> {
  const merged: Record<string, number> = {};
  const isReels = isInstagramReelsMediaType(mediaType);

  Object.assign(
    merged,
    await fetchIgMediaInsightMetrics(mediaId, accessToken, {
      metric: "reach,views,total_interactions,shares",
      metric_type: "total_value",
    }),
  );

  if (!isReels || (merged.views ?? 0) === 0) {
    Object.assign(
      merged,
      await fetchIgMediaInsightMetrics(mediaId, accessToken, {
        metric: "impressions",
        period: "lifetime",
      }),
    );
  }

  if ((merged.views ?? 0) === 0 && !isReels) {
    Object.assign(
      merged,
      await fetchIgMediaInsightMetrics(mediaId, accessToken, {
        metric: "impressions,reach,engagement",
        period: "lifetime",
      }),
    );
  }

  if ((merged.reach ?? 0) === 0) {
    Object.assign(
      merged,
      await fetchIgMediaInsightMetrics(mediaId, accessToken, {
        metric: "reach",
        period: "lifetime",
      }),
    );
  }

  if ((merged.total_interactions ?? 0) === 0 && (merged.engagement ?? 0) === 0) {
    Object.assign(
      merged,
      await fetchIgMediaInsightMetrics(mediaId, accessToken, {
        metric: "engagement",
        period: "lifetime",
      }),
    );
  }

  if ((merged.shares ?? 0) === 0) {
    Object.assign(
      merged,
      await fetchIgMediaInsightMetrics(mediaId, accessToken, {
        metric: "shares",
        metric_type: "total_value",
      }),
    );
  }

  if (Math.max(merged.views ?? 0, merged.impressions ?? 0) === 0) {
    const fieldViews = await fetchInstagramMediaViewCountFromFields(mediaId, accessToken);
    if (fieldViews > 0) merged.views = fieldViews;
  }

  return merged;
}

async function fetchInstagramMediaInsightsMap(
  posts: MetaContentPost[],
  accessToken: string,
): Promise<Map<string, InstagramMediaInsights>> {
  const mergedById = new Map<string, Record<string, number>>();
  for (const post of posts) mergedById.set(post.id, {});

  if (posts.length === 0) return new Map();

  const nonReels = posts.filter((post) => !isInstagramReelsMediaType(post.media_type));
  const reels = posts.filter((post) => isInstagramReelsMediaType(post.media_type));

  await mergeIgInsightBatchPass(posts, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, {
      metric: "reach,views,total_interactions,shares",
      metric_type: "total_value",
    }));

  await mergeIgInsightBatchPass(nonReels, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, { metric: "impressions", period: "lifetime" }));

  const reelsNeedImpressions = reels.filter(
    (post) => (mergedById.get(post.id)?.views ?? 0) === 0,
  );
  await mergeIgInsightBatchPass(reelsNeedImpressions, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, { metric: "impressions", period: "lifetime" }));

  const needLegacyBundle = nonReels.filter((post) => {
    const merged = mergedById.get(post.id) ?? {};
    return Math.max(merged.views ?? 0, merged.impressions ?? 0) === 0;
  });
  await mergeIgInsightBatchPass(needLegacyBundle, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, {
      metric: "impressions,reach,engagement",
      period: "lifetime",
    }));

  const needReach = posts.filter((post) => (mergedById.get(post.id)?.reach ?? 0) === 0);
  await mergeIgInsightBatchPass(needReach, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, { metric: "reach", period: "lifetime" }));

  const needEngagement = posts.filter((post) => {
    const merged = mergedById.get(post.id) ?? {};
    return (merged.total_interactions ?? 0) === 0 && (merged.engagement ?? 0) === 0;
  });
  await mergeIgInsightBatchPass(needEngagement, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, { metric: "engagement", period: "lifetime" }));

  const needShares = posts.filter((post) => (mergedById.get(post.id)?.shares ?? 0) === 0);
  await mergeIgInsightBatchPass(needShares, accessToken, mergedById, (post) =>
    igInsightsRelativeUrl(post.id, { metric: "shares", metric_type: "total_value" }));

  const viewCountById = new Map<string, number>();
  const needViewFields = posts.filter((post) => {
    const merged = mergedById.get(post.id) ?? {};
    return Math.max(merged.views ?? 0, merged.impressions ?? 0) === 0;
  });
  await mergeIgMediaViewFieldsBatchPass(needViewFields, accessToken, viewCountById);

  const needIndividual = posts.filter((post) => {
    const merged = mergedById.get(post.id) ?? {};
    return Math.max(
      merged.views ?? 0,
      merged.impressions ?? 0,
      viewCountById.get(post.id) ?? 0,
    ) === 0;
  });
  await mapWithConcurrency(needIndividual, 4, async (post) => {
    const merged = await fetchInstagramMediaInsightsSingleMerged(
      post.id,
      accessToken,
      post.media_type,
    );
    mergedById.set(post.id, { ...(mergedById.get(post.id) ?? {}), ...merged });
  });

  const out = new Map<string, InstagramMediaInsights>();
  for (const post of posts) {
    const merged = mergedById.get(post.id) ?? {};
    const views = Math.max(
      merged.views ?? 0,
      merged.impressions ?? 0,
      viewCountById.get(post.id) ?? 0,
    );
    out.set(post.id, {
      reach: merged.reach ?? 0,
      views,
      total_interactions: merged.total_interactions ?? merged.engagement ?? 0,
      shares: merged.shares ?? 0,
    });
  }
  return out;
}

/** Max posts returned when paginating all-time (IG/FB publish list). */
export const META_CONTENT_ALL_TIME_MAX_POSTS = 500;
export const META_CONTENT_ALL_TIME_MAX_PAGES = 40;
export const META_CONTENT_DATED_MAX_POSTS = 50;

const IG_MEDIA_LIST_FIELDS =
  "id,caption,media_type,media_url,thumbnail_url,permalink,timestamp,comments_count,like_count,shares_count";

export async function fetchInstagramMedia(
  igUserId: string,
  accessToken: string,
  limit = 25,
): Promise<MetaContentPost[]> {
  const url = graphUrl(`${igUserId}/media`, {
    fields: IG_MEDIA_LIST_FIELDS,
    limit: String(Math.min(Math.max(limit, 1), 100)),
  });
  const data = await graphGet<{ data?: Array<Record<string, unknown>> }>(url, accessToken);
  return (data.data ?? []).map(mapIgMedia);
}

export type ResolveInstagramPostsOptions = {
  /** Paginate through entire publish history (no publish-date filter). */
  allTime?: boolean;
};

function timestampToUtcYmd(iso: string): string {
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) return "";
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function filterPostsByYmdRange(
  posts: MetaContentPost[],
  startYmd: string,
  endYmd: string,
): MetaContentPost[] {
  const start = startYmd.trim();
  const end = endYmd.trim();
  if (!start || !end) return posts;
  return posts.filter((post) => {
    if (!post.timestamp) return false;
    const ymd = timestampToUtcYmd(post.timestamp);
    if (!ymd) return false;
    return ymd >= start && ymd <= end;
  });
}

export function filterPostsByUnixRange(
  posts: MetaContentPost[],
  since: string,
  until: string,
): MetaContentPost[] {
  const sinceSec = Number(since);
  const untilSec = Number(until);
  if (!Number.isFinite(sinceSec) || !Number.isFinite(untilSec)) return posts;
  return posts.filter((post) => {
    if (!post.timestamp) return false;
    const postedSec = Math.floor(new Date(post.timestamp).getTime() / 1000);
    return postedSec >= sinceSec && postedSec <= untilSec;
  });
}

/**
 * Fetches IG media with cursor pagination.
 * - `allTime`: all published posts up to {@link META_CONTENT_ALL_TIME_MAX_POSTS}.
 * - `dateRange`: posts whose publish date falls in [startYmd, endYmd] up to `limit`.
 */
export async function resolveInstagramPostsForMetrics(
  igUserId: string,
  accessToken: string,
  limit: number,
  dateRange?: { startYmd: string; endYmd: string },
  options?: ResolveInstagramPostsOptions,
): Promise<MetaContentPost[]> {
  const filterByDate = Boolean(
    dateRange?.startYmd && dateRange?.endYmd && !options?.allTime,
  );
  const paginate = filterByDate || options?.allTime === true;

  if (!paginate) {
    return fetchInstagramMedia(igUserId, accessToken, limit);
  }

  const { startYmd, endYmd } = dateRange ?? { startYmd: "", endYmd: "" };
  const inRange: MetaContentPost[] = [];
  let after: string | undefined;
  const maxPages = options?.allTime ? META_CONTENT_ALL_TIME_MAX_PAGES : 25;
  const cap = options?.allTime ? META_CONTENT_ALL_TIME_MAX_POSTS : limit;

  for (let page = 0; page < maxPages && inRange.length < cap; page++) {
    const params: Record<string, string> = {
      fields: IG_MEDIA_LIST_FIELDS,
      limit: "50",
    };
    if (after) params.after = after;

    const data = await graphGet<{
      data?: Array<Record<string, unknown>>;
      paging?: { cursors?: { after?: string } };
    }>(graphUrl(`${igUserId}/media`, params), accessToken);

    const batch = (data.data ?? []).map(mapIgMedia);
    if (batch.length === 0) break;

    for (const post of batch) {
      if (filterByDate) {
        if (!post.timestamp) continue;
        const ymd = timestampToUtcYmd(post.timestamp);
        if (!ymd || ymd < startYmd || ymd > endYmd) continue;
      }
      inRange.push(post);
      if (inRange.length >= cap) break;
    }

    if (filterByDate && startYmd) {
      const oldest = batch[batch.length - 1];
      const oldestYmd = oldest?.timestamp ? timestampToUtcYmd(oldest.timestamp) : "";
      if (oldestYmd && oldestYmd < startYmd) break;
    }

    after = data.paging?.cursors?.after;
    if (!after) break;
  }

  return inRange;
}

type FbInsightMetricRow = {
  name?: string;
  values?: Array<{ value?: number }>;
  total_value?: { value?: number };
};

function parseFbInsightMetricValue(row: FbInsightMetricRow): number {
  if (row.total_value != null && Number.isFinite(Number(row.total_value.value))) {
    return Number(row.total_value.value);
  }
  return (row.values ?? []).reduce((acc, v) => acc + Number(v.value ?? 0), 0);
}

async function mapWithConcurrency<T, R>(
  items: T[],
  limit: number,
  fn: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  if (items.length === 0) return [];
  const results = new Array<R>(items.length);
  let cursor = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (cursor < items.length) {
      const index = cursor++;
      results[index] = await fn(items[index], index);
    }
  });
  await Promise.all(workers);
  return results;
}

async function fetchFacebookPostReactionCount(postId: string, accessToken: string): Promise<number> {
