] as const;

export function hasThreadsScopes(granted: string[]): boolean {
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return THREADS_OAUTH_SCOPE_LIST.some((s) => grantedSet.has(s.toLowerCase()));
}

export function metaGraphVersion(): string {
  return Deno.env.get("META_GRAPH_API_VERSION")?.trim() || "v22.0";
}

export function missingScopesForFeature(
  granted: string[],
  feature: keyof typeof META_SCOPE_FEATURE_MAP,
): string[] {
  const required = META_SCOPE_FEATURE_MAP[feature];
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.filter((s) => !isScopeGranted(grantedSet, s));
}

export function hasAllScopes(granted: string[], required: readonly string[]): boolean {
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.every((s) => isScopeGranted(grantedSet, s));
}

export function missingScopesForInstagramPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "publish");
}

export function missingScopesForFacebookPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "facebook_publish");
}

export function instagramPublishScopesOk(granted: string[]): boolean {
  return missingScopesForInstagramPublish(granted).length === 0;
}

export function facebookPublishScopesOk(granted: string[]): boolean {
  return missingScopesForFacebookPublish(granted).length === 0;
}

export async function fetchGrantedPermissions(
  accessToken: string,
  appId?: string,
): Promise<string[]> {
  const version = metaGraphVersion();
  const debugUrl = appId?.trim()
    ? `https://graph.facebook.com/${version}/debug_token?input_token=${encodeURIComponent(accessToken)}&access_token=${encodeURIComponent(appId)}|${encodeURIComponent(Deno.env.get("META_APP_SECRET") ?? "")}`
    : null;

  if (debugUrl) {
    try {
      const res = await fetch(debugUrl);
      const data = await res.json().catch(() => ({})) as {
        data?: { scopes?: string[] };
      };
      if (res.ok && Array.isArray(data?.data?.scopes)) {
        return data.data.scopes.map((s) => String(s));
      }
    } catch {
      /* fall through */
    }
  }

  const permUrl = `https://graph.facebook.com/${version}/me/permissions?access_token=${encodeURIComponent(accessToken)}`;
  const permRes = await fetch(permUrl);
  const permData = await permRes.json().catch(() => ({})) as {
    data?: Array<{ permission?: string; status?: string }>;
  };
  if (!permRes.ok || !Array.isArray(permData?.data)) return [];
  return permData.data
    .filter((p) => p.status === "granted" && p.permission)
    .map((p) => String(p.permission));
}

/**
 * Canonical Meta WhatsApp template helpers (campaign worker + livechat follow-up).
 * Supabase deploy bundles one function folder at a time — `../_shared` is not included.
 * After editing this file, run: `node scripts/sync-wa-template-graph.mjs`
 * (copies into whatsapp-campaign-worker/ and send-whatsapp-template-followup/).
 */

export function countPlaceholders(text: string): number {
  return (text.match(/\{\{[^}]+\}\}/g) ?? []).length;
}

const MEDIA_HEADER_FORMATS = new Set(["IMAGE", "VIDEO", "DOCUMENT"]);

/** Fallback when a mapped field is empty — ASCII hyphen (Meta-safe). */
const EMPTY_PARAM = "-";

function extractHttpsHeaderMediaUrl(c: Record<string, unknown>): string | null {
  const ex = c.example;
  if (!ex || typeof ex !== "object") return null;
  const handles = (ex as { header_handle?: unknown }).header_handle;
  if (!Array.isArray(handles)) return null;
  for (const h of handles) {
    const s = String(h ?? "").trim();
    if (/^https?:\/\//i.test(s)) return s;
  }
  return null;
}

function normalizeParamValue(raw: unknown): string {
  const s = String(raw ?? "").trim();
  return s.length > 0 ? s.slice(0, 1024) : EMPTY_PARAM;
}

type TextPlaceholderSection = {
  kind: "header_text" | "body" | "button_url";
  placeholderCount: number;
  buttonIndex?: number;
};

/** Sections that consume entries from flat `parameter_values` in Meta order. */
function listTextPlaceholderSections(components: unknown[]): TextPlaceholderSection[] {
  const sections: TextPlaceholderSection[] = [];
  if (!Array.isArray(components)) return sections;

  for (const raw of components) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    const type = String(c.type ?? "").toUpperCase();

    if (type === "HEADER") {
      const fmt = String(c.format ?? "TEXT").toUpperCase();
      if (!MEDIA_HEADER_FORMATS.has(fmt)) {
        const n = countPlaceholders(String(c.text ?? ""));
        if (n > 0) sections.push({ kind: "header_text", placeholderCount: n });
      } else {
        const n = countPlaceholders(String(c.text ?? ""));
        if (n > 0) sections.push({ kind: "header_text", placeholderCount: n });
      }
      continue;
    }

    if (type === "BODY") {
      const n = countPlaceholders(String(c.text ?? ""));
      if (n > 0) sections.push({ kind: "body", placeholderCount: n });
      continue;
    }

    if (type === "BUTTONS") {
      const buttons = c.buttons;
      if (!Array.isArray(buttons)) continue;
      buttons.forEach((btn, buttonIndex) => {
        if (!btn || typeof btn !== "object") return;
        const bt = String((btn as { type?: string }).type ?? "").toUpperCase();
        if (bt !== "URL") return;
        const n = countPlaceholders(String((btn as { url?: string }).url ?? ""));
        if (n > 0) sections.push({ kind: "button_url", placeholderCount: n, buttonIndex });
      });
    }
  }

  return sections;
}

export type BuildGraphTemplateResult =
  | { ok: true; components: Array<Record<string, unknown>> }
  | { ok: false; reason: string };

export function isTemplateBuildFailure(
  result: BuildGraphTemplateResult,
): result is Extract<BuildGraphTemplateResult, { ok: false }> {
  return result.ok === false;
}

export type PostTemplateMessageResult =
  | { ok: true; wa_message_id: string; metaData: Record<string, unknown> }
  | { ok: false; status: number; body: string };

export function isPostTemplateMessageFailure(
  result: PostTemplateMessageResult,
): result is Extract<PostTemplateMessageResult, { ok: false }> {
  return result.ok === false;
}

/**
 * Build Graph API `template.components` from Meta template definition + flat parameter values.
 * Order: HEADER text vars → BODY vars → dynamic URL button vars (matches Meta {{1}}…{{n}}).
 * Media headers use sample HTTPS URL from template example (not from parameter_values).
 */
export function buildGraphTemplateComponents(
  templateComponents: unknown[],
  parameterValues: unknown,
  options?: { allowMediaHeader?: boolean },
): BuildGraphTemplateResult {
  const allowMediaHeader = options?.allowMediaHeader !== false;
  const params = Array.isArray(parameterValues)
    ? parameterValues.map((x) => normalizeParamValue(x))
    : [];
  let idx = 0;
  const out: Array<Record<string, unknown>> = [];
  if (!Array.isArray(templateComponents)) return { ok: true, components: [] };

  const expectedSlots = countTemplateParameterSlots(templateComponents);
  if (params.length < expectedSlots) {
    return {
      ok: false,
      reason: `Template expects ${expectedSlots} variable(s) but received ${params.length}.`,
    };
  }

  for (const raw of templateComponents) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    const type = String(c.type ?? "").toUpperCase();

    if (type === "HEADER") {
      const fmt = String(c.format ?? "TEXT").toUpperCase();
      if (MEDIA_HEADER_FORMATS.has(fmt)) {
        if (!allowMediaHeader) {
          return { ok: false, reason: "Media header templates are not supported for this send path yet." };
        }
        const text = String(c.text ?? "");
        const n = countPlaceholders(text);
        if (n > 0) {
          const parameters: { type: string; text: string }[] = [];
          for (let i = 0; i < n; i++) {
            parameters.push({ type: "text", text: params[idx++] ?? EMPTY_PARAM });
          }
          out.push({ type: "header", parameters });
        }
        const mediaUrl = extractHttpsHeaderMediaUrl(c);
        if (mediaUrl) {
          const fmtLower = fmt.toLowerCase();
          const paramType = fmtLower === "document" ? "document" : fmtLower === "video" ? "video" : "image";
          out.push({
            type: "header",
            parameters: [
              {
                type: paramType,
                [paramType]: { link: mediaUrl },
              },
            ],
          });
        } else if (n === 0) {
          return {
            ok: false,
            reason:
              "Template has a media header but no public sample URL (header_handle). Re-sync template from Meta or use a template with a text header.",
          };
        }
        continue;
      }
      const text = String(c.text ?? "");
      const n = countPlaceholders(text);
      if (n === 0) continue;
      const parameters: { type: string; text: string }[] = [];
      for (let i = 0; i < n; i++) {
        parameters.push({ type: "text", text: params[idx++] ?? EMPTY_PARAM });
      }
      out.push({ type: "header", parameters });
    } else if (type === "BODY") {
      const text = String(c.text ?? "");
      const n = countPlaceholders(text);
      if (n === 0) continue;
      const parameters: { type: string; text: string }[] = [];
      for (let i = 0; i < n; i++) {
        parameters.push({ type: "text", text: params[idx++] ?? EMPTY_PARAM });
      }
      out.push({ type: "body", parameters });
    } else if (type === "BUTTONS") {
      const buttons = c.buttons;
      if (!Array.isArray(buttons)) continue;
      buttons.forEach((btn, buttonIndex) => {
        if (!btn || typeof btn !== "object") return;
        const b = btn as Record<string, unknown>;
        const bt = String(b.type ?? "").toUpperCase();
        if (bt !== "URL") return;
        const n = countPlaceholders(String(b.url ?? ""));
        if (n === 0) return;
        const parameters: { type: string; text: string }[] = [];
        for (let i = 0; i < n; i++) {
          parameters.push({ type: "text", text: params[idx++] ?? EMPTY_PARAM });
        }
        out.push({
          type: "button",
          sub_type: "url",
          index: String(buttonIndex),
          parameters,
        });
      });
    }
  }

  if (idx < expectedSlots) {
    return {
      ok: false,
      reason: `Only ${idx} of ${expectedSlots} template variable(s) were applied when building the message.`,
    };
  }

  return { ok: true, components: out };
}

export function countTemplateParameterSlots(components: unknown[] | null | undefined): number {
  return listTextPlaceholderSections(Array.isArray(components) ? components : []).reduce(
    (sum, s) => sum + s.placeholderCount,
    0,
  );
}

/** Human-readable outbound body for whatsapp_messages.storage */
export function renderTemplateBodyPreview(
  templateName: string,
  templateComponents: unknown[] | null | undefined,
  parameterValues: unknown,
): string {
  const params = Array.isArray(parameterValues)
    ? parameterValues.map((x) => normalizeParamValue(x))
    : [];
  let idx = 0;
  const parts: string[] = [`[Template: ${templateName}]`];
  if (!Array.isArray(templateComponents)) return parts.join("\n");

  for (const raw of templateComponents) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    const type = String(c.type ?? "").toUpperCase();
    if (type === "HEADER") {
      const fmt = String(c.format ?? "TEXT").toUpperCase();
      if (MEDIA_HEADER_FORMATS.has(fmt)) {
        parts.push(`[${fmt}]`);
        const n = countPlaceholders(String(c.text ?? ""));
        for (let i = 0; i < n; i++) idx++;
        continue;
      }
      let text = String(c.text ?? "");
      const n = countPlaceholders(text);
      for (let i = 0; i < n; i++) {
        const val = params[idx++] ?? EMPTY_PARAM;
        text = text.replace(/\{\{[^}]+\}\}/, val);
      }
      if (text.trim()) parts.push(text.trim());
    } else if (type === "BODY") {
      let text = String(c.text ?? "");
      const n = countPlaceholders(text);
      for (let i = 0; i < n; i++) {
        const val = params[idx++] ?? EMPTY_PARAM;
        text = text.replace(/\{\{[^}]+\}\}/, val);
      }
      if (text.trim()) parts.push(text.trim());
    } else if (type === "BUTTONS") {
      const buttons = c.buttons;
      if (!Array.isArray(buttons)) continue;
      for (const btn of buttons) {
        if (!btn || typeof btn !== "object") continue;
        const b = btn as Record<string, unknown>;
        if (String(b.type ?? "").toUpperCase() !== "URL") continue;
        const n = countPlaceholders(String(b.url ?? ""));
        for (let i = 0; i < n; i++) idx++;
      }
    }
  }
  return parts.join("\n").slice(0, 4090);
}

export const META_API_BASE = "https://graph.facebook.com/v18.0";

export async function postTemplateMessage(
  phoneNumberId: string,
  accessToken: string,
  toDigits: string,
  templateName: string,
  templateLanguage: string,
  components: Array<Record<string, unknown>>,
): Promise<PostTemplateMessageResult> {
  const url = `${META_API_BASE}/${encodeURIComponent(phoneNumberId)}/messages`;
  const template: Record<string, unknown> = {
    name: templateName,
    language: { code: templateLanguage },
  };
  if (components.length > 0) template.components = components;

  let lastText = "";
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        messaging_product: "whatsapp",
        to: toDigits,
        type: "template",
        template,
      }),
    });
    lastText = await res.text();
    if (res.status === 429 || (res.status >= 500 && res.status <= 599)) {
      await new Promise((r) => setTimeout(r, 650 * (attempt + 1)));
      continue;
    }
    if (!res.ok) return { ok: false, status: res.status, body: lastText.slice(0, 4000) };
    let json: Record<string, unknown> = {};
    try {
      json = JSON.parse(lastText) as Record<string, unknown>;
    } catch {
      return { ok: false, status: res.status, body: lastText.slice(0, 4000) };
    }
    const messages = json?.messages as unknown[] | undefined;
    const first = messages?.[0] as Record<string, unknown> | undefined;
    const mid = first?.id != null ? String(first.id).trim() : "";
    if (!mid) return { ok: false, status: 500, body: lastText.slice(0, 4000) };
    return { ok: true, wa_message_id: mid, metaData: json };
  }
  return { ok: false, status: 429, body: lastText.slice(0, 4000) };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const STATUS_MAP: Record<string, string[]> = {
  new: ["Open", "New"],
  contacted: ["On Progress", "Contacted", "In Progress"],
  deal: ["Converted", "Deal", "Closed Won"],
  lost: ["Lost", "Closed", "Closed Lost"],
};

export async function resolveLeadStatusId(
  admin: SupabaseClient,
  organizationId: string,
  apiStatus?: string | null,
): Promise<string | null> {
  const key = (apiStatus ?? "new").trim().toLowerCase();
  const candidates = STATUS_MAP[key] ?? STATUS_MAP.new;

  for (const name of candidates) {
    const { data } = await admin
      .from("lead_statuses")
      .select("id")
      .eq("organization_id", organizationId)
      .ilike("name", name)
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    if (data?.id) return data.id as string;
  }

  const { data: fallback } = await admin
    .from("lead_statuses")
    .select("id")
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .order("sort_order", { ascending: true })
    .limit(1)
    .maybeSingle();

  return (fallback?.id as string | undefined) ?? null;
}

export async function resolveConvertedStatusId(
  admin: SupabaseClient,
  organizationId: string,
): Promise<string | null> {
  return resolveLeadStatusId(admin, organizationId, "deal");
}

export async function getOrCreateSystemActor(
  admin: SupabaseClient,
  organizationId: string,
): Promise<{ userId: string; displayName: string }> {
  const { data, error } = await admin.rpc("get_or_create_org_api_system_actor", {
    p_organization_id: organizationId,
  });

  if (error) throw error;
  const row = Array.isArray(data) ? data[0] : data;
  if (!row?.user_id) {
    throw new Error("System actor tidak ditemukan untuk organisasi ini.");
  }
  return {
    userId: String(row.user_id),
    displayName: String(row.display_name ?? "Synckerja API"),
  };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  buildWaTicketId,
  digitsOnly,
  resolveLeadStatusIdByName,
} from "./whatsappConversationForLead.ts";

export type PersistLeadWhatsAppThreadArgs = {
  organizationId: string;
  leadId: string;
  webId: string;
  phoneNumber: string;
  customerName: string;
  waMessageId: string;
  templateName: string;
  templateLanguage: string;
  bodyPreview: string;
  bodyParams?: string[];
  rawMetadata?: Record<string, unknown> | null;
  whatsappAccountId: string;
  phoneNumberId: string;
  /** When set, tags outbound as Lead Magnet (webhook fallback + debugging). */
  leadMagnetMeta?: {
    enrollmentId: string;
    campaignId: string;
  };
};

export type PersistLeadWhatsAppThreadResult =
  | { ok: true; conversationId: string; ticketId: string; messageRowId: string | null }
  | { ok: false; error: string };

function parseWabaExpirationUnixSeconds(meta: Record<string, unknown> | null | undefined): number | null {
  if (!meta) return null;
  const messages = meta.messages as unknown[] | undefined;
  const first = messages?.[0] as Record<string, unknown> | undefined;
  const conv = first?.conversation as { expiration_timestamp?: string | number } | undefined;
  const raw = conv?.expiration_timestamp;
  if (raw == null) return null;
  const n = typeof raw === "string" ? Number.parseInt(raw, 10) : Number(raw);
  return Number.isFinite(n) && n > 0 ? n : null;
}

async function insertWhatsAppMessageCompat(
  admin: SupabaseClient,
  payload: Record<string, unknown>,
): Promise<{ id: string | null; error: string | null }> {
  const compatibilityPayload: Record<string, unknown> = { ...payload };
  const dropColumnsInOrder = ["status", "platform_message_id", "channel"] as const;

  for (const col of [null, ...dropColumnsInOrder]) {
    if (col) delete compatibilityPayload[col];
    const attempt = await admin
      .from("whatsapp_messages")
      .insert(compatibilityPayload)
      .select("id")
      .single();
    if (!attempt.error) {
      const id = attempt.data?.id != null ? String(attempt.data.id) : null;
      return { id, error: null };
    }
    const code = (attempt.error as { code?: string }).code;
    if (code !== "PGRST204") {
      return { id: null, error: attempt.error.message ?? "insert failed" };
    }
  }
  return { id: null, error: "whatsapp_messages insert failed" };
}

/** Persist outbound lead API template as livechat thread + merge LEAD ticket to WA ticket. */
export async function persistLeadWhatsAppThread(
  admin: SupabaseClient,
  args: PersistLeadWhatsAppThreadArgs,
): Promise<PersistLeadWhatsAppThreadResult> {
  try {
    const phoneDigits = digitsOnly(args.phoneNumber);
    if (phoneDigits.length < 8) {
      return { ok: false, error: "Nomor telepon tidak valid untuk conversation." };
    }

    const { data: lead } = await admin
      .from("leads")
      .select("id, client, title, ticket_id, assignee_id")
      .eq("id", args.leadId)
      .eq("organization_id", args.organizationId)
      .maybeSingle();
    if (!lead) return { ok: false, error: "Lead not found." };

    const pnId = String(args.phoneNumberId).trim();
    const customerName = String(args.customerName ?? lead.client ?? lead.title ?? "").trim() || phoneDigits;
    const now = new Date().toISOString();
    const unreadStatusId = await resolveLeadStatusIdByName(admin, args.organizationId, "Unread");

    const { data: existingConv } = await admin
      .from("whatsapp_conversations")
      .select("id, ticket_id")
      .eq("organization_id", args.organizationId)
      .eq("customer_wa_id", phoneDigits)
      .eq("channel", "whatsapp")
      .eq("phone_number_id", pnId)
      .maybeSingle();

    let conversationId: string;

    if (existingConv?.id) {
      conversationId = String(existingConv.id);
    } else {
      const { data: inserted, error: insertErr } = await admin
        .from("whatsapp_conversations")
        .insert({
          organization_id: args.organizationId,
          customer_wa_id: phoneDigits,
          customer_external_id: phoneDigits,
          customer_name: customerName,
          channel: "whatsapp",
          phone_number_id: pnId,
          assignee_id: lead.assignee_id ?? null,
          last_message_at: now,
          last_message_body: "",
          updated_at: now,
          ...(unreadStatusId ? { lead_status_id: unreadStatusId } : {}),
        })
        .select("id")
        .single();

      if (insertErr || !inserted?.id) {
        console.error("persistLeadWhatsAppThread conv insert:", insertErr);
        return { ok: false, error: insertErr?.message ?? "Conversation insert failed." };
      }
      conversationId = String(inserted.id);
    }

    const waTicketId =
      (existingConv?.ticket_id as string | null)?.trim() || buildWaTicketId(conversationId);

    const { data: waTicketLead } = await admin
      .from("leads")
      .select("id")
      .eq("organization_id", args.organizationId)
      .eq("ticket_id", waTicketId)
      .maybeSingle();

    if (waTicketLead?.id && waTicketLead.id !== args.leadId) {
      const { error: delErr } = await admin.from("leads").delete().eq("id", waTicketLead.id);
      if (delErr) {
        console.error("persistLeadWhatsAppThread: delete duplicate WA lead failed", delErr);
      }
    }

    const lastBody = args.bodyPreview.slice(0, 200);
    const convUpdate: Record<string, unknown> = {
      customer_name: customerName,
      last_message_at: now,
      last_message_body: lastBody,
      updated_at: now,
    };
    if (unreadStatusId) convUpdate.lead_status_id = unreadStatusId;
    if (lead.assignee_id) convUpdate.assignee_id = lead.assignee_id;

    const expSec = parseWabaExpirationUnixSeconds(args.rawMetadata ?? null);
    if (expSec != null) {
      convUpdate.meta_session_expires_at = new Date(expSec * 1000).toISOString();
    }

    const { error: convUpErr } = await admin
      .from("whatsapp_conversations")
      .update(convUpdate)
      .eq("id", conversationId);
    if (convUpErr) {
      console.error("persistLeadWhatsAppThread conv update:", convUpErr);
      return { ok: false, error: convUpErr.message };
    }

    const { data: existingMsg } = await admin
      .from("whatsapp_messages")
      .select("id")
      .eq("wa_message_id", args.waMessageId)
      .maybeSingle();

    let messageRowId: string | null = existingMsg?.id ? String(existingMsg.id) : null;

    if (!messageRowId) {
      const insertPayload: Record<string, unknown> = {
        conversation_id: conversationId,
        direction: "outbound",
        wa_message_id: args.waMessageId,
        platform_message_id: args.waMessageId,
        channel: "whatsapp",
        body: args.bodyPreview,
        message_type: "template",
        raw_metadata: {
          ...(args.rawMetadata ?? {}),
          ...(args.leadMagnetMeta
            ? {
                synckerja_lead_magnet: {
                  lead_id: args.leadId,
                  enrollment_id: args.leadMagnetMeta.enrollmentId,
                  campaign_id: args.leadMagnetMeta.campaignId,
                  organization_id: args.organizationId,
                  template_name: args.templateName,
                  template_language: args.templateLanguage,
                  parameter_values: args.bodyParams ?? [],
                  whatsapp_account_id: args.whatsappAccountId,
                },
              }
            : {
                synckerja_lead_api: {
                  lead_id: args.leadId,
                  web_id: args.webId,
                  template_name: args.templateName,
                  template_language: args.templateLanguage,
                  parameter_values: args.bodyParams ?? [],
                  whatsapp_account_id: args.whatsappAccountId,
                },
              }),
        },
        status: "sent",
      };

      const inserted = await insertWhatsAppMessageCompat(admin, insertPayload);
      if (inserted.error && !inserted.id) {
        console.error("persistLeadWhatsAppThread message insert:", inserted.error);
        return { ok: false, error: inserted.error };
      }
      messageRowId = inserted.id;
    }

    const leadUpdate: Record<string, unknown> = {
      ticket_id: waTicketId,
      phone_number: phoneDigits,
      services: "WhatsApp",
      updated_at: now,
    };
    if (unreadStatusId) leadUpdate.status_id = unreadStatusId;

    const { error: leadUpErr } = await admin
      .from("leads")
      .update(leadUpdate)
      .eq("id", args.leadId)
      .eq("organization_id", args.organizationId);
    if (leadUpErr) {
      console.error("persistLeadWhatsAppThread lead ticket merge:", leadUpErr);
    }

    return { ok: true, conversationId, ticketId: waTicketId, messageRowId };
  } catch (e) {
    console.error("persistLeadWhatsAppThread:", e);
    return {
      ok: false,
      error: e instanceof Error ? e.message : "Unknown persist error",
    };
  }
}

export function buildLeadTemplateBodyPreview(templateName: string, paramPreview?: string | null): string {
  const name = templateName.trim();
  const extra = paramPreview?.trim();
  if (extra) return `[Template: ${name}] ${extra}`.slice(0, 200);
  return `[Template: ${name}]`.slice(0, 200);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const WA_TICKET_PREFIX = "WA-";

export function digitsOnly(value: string | null | undefined): string {
  return String(value ?? "").replace(/\D/g, "");
}

export function buildWaTicketId(conversationId: string): string {
  return `${WA_TICKET_PREFIX}${conversationId.replace(/-/g, "").slice(0, 8).toUpperCase()}`;
}

export async function resolveLeadStatusIdByName(
  admin: SupabaseClient,
  organizationId: string,
  name: string,
): Promise<string | null> {
  const { data: orgStatus } = await admin
    .from("lead_statuses")
    .select("id")
    .eq("organization_id", organizationId)
    .eq("name", name)
    .maybeSingle();
  if (orgStatus?.id) return String(orgStatus.id);

  const { data: globalStatus } = await admin
    .from("lead_statuses")
    .select("id")
    .is("organization_id", null)
    .eq("name", name)
    .maybeSingle();
  return globalStatus?.id ? String(globalStatus.id) : null;
}

/** Find or create WA conversation for a CRM lead (used by template follow-up). */
export async function findOrCreateConversationForLead(
  admin: SupabaseClient,
  orgId: string,
  leadId: string,
  phoneDigits: string,
  waAccount: { id: string; phone_number_id: string },
): Promise<{ conversationId: string; ticketId: string; created: boolean } | null> {
  const { data: lead } = await admin
    .from("leads")
    .select("id, client, title, ticket_id, assignee_id, organization_id")
    .eq("id", leadId)
    .eq("organization_id", orgId)
    .maybeSingle();
  if (!lead) return null;

  const pnId = String(waAccount.phone_number_id).trim();
  const { data: existingConv } = await admin
    .from("whatsapp_conversations")
    .select("id, ticket_id")
    .eq("organization_id", orgId)
    .eq("customer_wa_id", phoneDigits)
    .eq("channel", "whatsapp")
    .eq("phone_number_id", pnId)
    .maybeSingle();

  const now = new Date().toISOString();
  const customerName = String(lead.client ?? lead.title ?? "").trim() || phoneDigits;

  if (existingConv?.id) {
    const convId = String(existingConv.id);
    const ticketId =
      (existingConv.ticket_id as string | null)?.trim() || buildWaTicketId(convId);
    await admin
      .from("whatsapp_conversations")
      .update({
        assignee_id: lead.assignee_id ?? undefined,
        updated_at: now,
      })
      .eq("id", convId);
    const leadTicket = (lead.ticket_id as string | null)?.trim() ?? "";
    if (!leadTicket.startsWith(WA_TICKET_PREFIX)) {
      await admin
        .from("leads")
        .update({ ticket_id: ticketId, phone_number: phoneDigits, updated_at: now })
        .eq("id", leadId);
    }
    return { conversationId: convId, ticketId, created: false };
  }

  const { data: inserted, error: insertErr } = await admin
    .from("whatsapp_conversations")
    .insert({
      organization_id: orgId,
      customer_wa_id: phoneDigits,
      customer_external_id: phoneDigits,
      customer_name: customerName,
      channel: "whatsapp",
      phone_number_id: pnId,
      assignee_id: lead.assignee_id ?? null,
      last_message_at: now,
      last_message_body: "",
      updated_at: now,
    })
    .select("id, ticket_id")
    .single();

  if (insertErr || !inserted?.id) {
    console.error("findOrCreateConversationForLead insert error:", insertErr);
    return null;
  }

  const convId = String(inserted.id);
  const finalTicket =
    (inserted.ticket_id as string | null)?.trim() || buildWaTicketId(convId);
  await admin
    .from("leads")
    .update({ ticket_id: finalTicket, phone_number: phoneDigits, updated_at: now })
    .eq("id", leadId);

  return { conversationId: convId, ticketId: finalTicket, created: true };
}

export async function resolveLeadPhoneDigits(
  admin: SupabaseClient,
  leadId: string,
): Promise<string | null> {
  const { data: lead } = await admin
    .from("leads")
    .select("phone_number")
    .eq("id", leadId)
    .maybeSingle();
  let phone = lead?.phone_number != null ? String(lead.phone_number).trim() : "";
  if (!phone) {
    const { data: submissions } = await admin
      .from("lead_submissions")
      .select("phone_number, status, submitted_at, updated_at")
      .eq("lead_id", leadId)
      .eq("is_active", true)
      .order("status", { ascending: true })
      .order("submitted_at", { ascending: false, nullsFirst: false })
      .order("updated_at", { ascending: false });
    const rows = submissions ?? [];
    const submitted = rows.find((r) => r.status === "submitted");
    const draft = rows.find((r) => r.status === "draft");
    const picked = submitted ?? draft ?? rows[0];
    phone = picked?.phone_number != null ? String(picked.phone_number).trim() : "";
  }
  const digits = digitsOnly(phone);
  return digits.length >= 8 ? digits : null;
}
